```python
from typing import TypedDict

from langgraph.graph import (
    StateGraph,
    START,
    END
)

class SupportState(TypedDict):
    order_id: str
    delayed_hours: int
    eligible: bool
    response: str

def investigate(state):

    # Synthetic API response
    return {"delayed_hours": 72}

def evaluate_policy(state):

    return {
        "eligible": state["delayed_hours"] > 48
    }

def route(state):

    if state["eligible"]:
        return "prepare_review"

    return "respond"

def prepare_review(state):

    return {
        "response": (
            "Order qualifies for support review. "
            "No compensation has been issued."
        )
    }

def respond(state):

    return {
        "response": (
            "Order does not qualify under "
            "the current delay policy."
        )
    }

builder = StateGraph(SupportState)

builder.add_node("investigate", investigate)
builder.add_node("evaluate", evaluate_policy)
builder.add_node("prepare_review", prepare_review)
builder.add_node("respond", respond)

builder.add_edge(START, "investigate")
builder.add_edge("investigate", "evaluate")

builder.add_conditional_edges(
    "evaluate",
    route,
    {
        "prepare_review": "prepare_review",
        "respond": "respond"
    }
)

builder.add_edge("prepare_review", END)
builder.add_edge("respond", END)

graph = builder.compile()

result = graph.invoke({
    "order_id": "ORD-101",
    "delayed_hours": 0,
    "eligible": False,
    "response": ""
})

print(result["response"])
```

Notice that this graph does not need an LLM. It is a deterministic business workflow.

The advantage is that we can insert LLM-powered decisions only where natural-language understanding or dynamic planning is necessary.
